import { Component, inject, signal } from '@angular/core'
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms'
import { API, NAVIGATE } from '../app/tokens'

function today(): string {
  const d = new Date()
  const two = (n: number): string => String(n).padStart(2, '0')
  return `${two(d.getDate())}/${two(d.getMonth() + 1)}/${two(d.getFullYear() % 100)}`
}

@Component({
  selector: 'app-pagomen-screen',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <main class="nx-root nx-screen" aria-label="BANCO FICTICIO - PAGOS">
      <header class="nx-screen__header">
        <h1 class="nx-screen__title">BANCO FICTICIO - PAGOS</h1>
      </header>
      <div class="nx-screen__body">
        <form [formGroup]="form" (ngSubmit)="submit()" novalidate>
          <div class="nx-field" data-field="FECHA">
            <span class="nx-field__label">FECHA</span>
            <span>{{ fecha }}</span>
          </div>

          <section class="nx-card">
            <p>1 - Pagar una orden</p>
            <p>2 - Consultar una orden</p>

            <div class="nx-field" data-field="OPCION">
              <label class="nx-field__label" for="opcion">OPCION</label>
              <input
                id="opcion"
                class="nx-input"
                type="text"
                formControlName="opcion"
                maxlength="1"
                inputmode="numeric"
                required
                (input)="onInput($event)"
              />
              @if (opcionError()) {
                <p class="nx-field__error" role="alert">{{ opcionError() }}</p>
              }
            </div>

            <div class="nx-field">
              <button class="nx-button nx-button--primary" type="submit" data-action="ENTER">CONTINUAR</button>
              <button class="nx-button nx-button--secondary" type="button" data-action="PF3" (click)="exit()">SALIR</button>
            </div>
          </section>

          <div class="nx-field" data-field="MENSAJE" aria-live="polite">
            <span class="nx-field__label">MENSAJE</span>
            @if (mensajeError()) {
              <p class="nx-alert nx-alert--error">{{ mensajeError() }}</p>
            } @else {
              <p>{{ mensajeInfo() }}</p>
            }
          </div>
        </form>
      </div>
    </main>
  `,
})
export class PagomenScreen {
  protected readonly api = inject(API)
  private readonly navigate = inject(NAVIGATE)

  readonly fecha = today()

  readonly form = new FormGroup({
    opcion: new FormControl('', { nonNullable: true, validators: [Validators.required] }),
  })

  readonly opcionError = signal('')
  readonly mensajeError = signal('')
  readonly mensajeInfo = signal('')

  onInput(event: Event): void {
    const target = event.target as HTMLInputElement
    const clean = target.value.replace(/\D/g, '').slice(0, 1)
    if (clean !== target.value) {
      target.value = clean
    }
    this.form.controls.opcion.setValue(clean)
    this.opcionError.set('')
    this.mensajeError.set('')
    this.mensajeInfo.set('')
  }

  submit(): void {
    this.mensajeError.set('')
    this.mensajeInfo.set('')
    const opcion = this.form.controls.opcion.value.trim()
    if (opcion === '') {
      this.opcionError.set('Debe ingresar una opción.')
      return
    }
    this.opcionError.set('')
    if (opcion !== '1' && opcion !== '2') {
      this.mensajeError.set('Opción inválida. Ingrese 1 o 2.')
      return
    }
    this.navigate('SCR-PAGOORD')
  }

  exit(): void {
    this.opcionError.set('')
    this.mensajeError.set('')
    this.mensajeInfo.set('Sesión de pagos finalizada.')
  }
}
